import threading, time

def run(safe):
    stock = [1000]; issued = [0]; lock = threading.Lock()
    def naive():
        for _ in range(300):
            if stock[0] > 0:
                s = stock[0]          # 잔량을 읽고
                time.sleep(0)         # 다른 요청이 끼어든다
                stock[0] = s - 1      # 나중에 쓴다
                issued[0] += 1
    def atomic():
        for _ in range(300):
            with lock:                # 확인+차감을 한 번에
                if stock[0] > 0:
                    stock[0] -= 1; issued[0] += 1
    ts = [threading.Thread(target=atomic if safe else naive) for _ in range(8)]
    [t.start() for t in ts]; [t.join() for t in ts]
    return issued[0], stock[0]

print("따로 확인·차감: 발급 %d장, 남은 재고 %d" % run(False))
print("한 번에 확인·차감: 발급 %d장, 남은 재고 %d" % run(True))
